# The root is svg, its children are g
for g in root.findall('.//{http://www.w3.org/2000/svg}g'):
    # let's just find all paths
    pass
    
# Actually just regex without ElementTree is fine:
import re
paths = re.findall(r'<path[^>]*d="([^"]+)"', svg_content)
for i, p in enumerate(paths):
    nums = [float(n) for n in re.findall(r'[+-]?\d+\.?\d*', p)]
    if len(nums) < 2:
        continue
    xs = nums[0::2]
    ys = nums[1::2]
    print(f"Path {i}: minX={min(xs):.1f} maxX={max(xs):.1f} minY={min(ys):.1f} maxY={max(ys):.1f} width={max(xs)-min(xs):.1f} height={max(ys)-min(ys):.1f}")
